  x.strokeStyle='rgba(125,190,230,.12)';x.lineWidth=1;x.beginPath();for(var i=-9;i<=9;i++){x.moveTo(pl.X(i),0);x.lineTo(pl.X(i),H);x.moveTo(0,pl.Y(i));x.lineTo(W,pl.Y(i))}x.stroke();
