  var px=pl.X(pt[0]),py=pl.Y(pt[1]);x.strokeStyle=sc;x.setLineDash([5,5]);x.lineWidth=1.5;x.beginPath();x.moveTo(cx,cy);x.lineTo(px,py);x.stroke();x.setLineDash([]);dot(x,cx,cy,5,'#fff');
