/* ---------------- HSC concept labs: compact, interactive models ---------------- */
function formulaLab(root, cfg, done){
 var html='<div class="formula-lab"><p class="fl-intro">'+cfg.intro+'</p><div class="fl-controls">'+cfg.inputs.map(function(a){return'<label><span>'+a.l+'</span><strong data-out="'+a.k+'">'+a.v+'</strong><input type="range" data-in="'+a.k+'" min="'+a.min+'" max="'+a.max+'" step="'+a.step+'" value="'+a.v+'" aria-label="'+a.l+'"></label>'}).join('')+'</div><div class="fl-visual" aria-label="Live model visualization"><div class="fl-bars">'+cfg.bars.map(function(b){return'<div class="fl-barrow"><span>'+b+'</span><div><i data-bar="'+b+'"></i></div><b data-barval="'+b+'">—</b></div>'}).join('')+'</div></div><div class="fl-results">'+cfg.labels.map(function(a,i){return'<div><small>'+a+'</small><strong data-result="'+i+'">—</strong></div>'}).join('')+'</div><p class="fl-note" data-note></p><p class="fl-caveat">শিক্ষামূলক মডেল: বাস্তব পরীক্ষায় আরও শর্ত ও সীমাবদ্ধতা থাকতে পারে।</p></div>';
 root.innerHTML=html;
 var vals={};cfg.inputs.forEach(function(a){vals[a.k]=a.v});
 function update(){
  var r=cfg.calc(vals), res=root.querySelectorAll('[data-result]'),note=root.querySelector('[data-note]');
  cfg.inputs.forEach(function(a){var o=root.querySelector('[data-out="'+a.k+'"]');if(o)o.textContent=vals[a.k]+(a.unit||'')});
  r.results.forEach(function(x,i){if(res[i])res[i].textContent=x});
  cfg.bars.forEach(function(b,i){var width=Math.max(3,Math.min(100,r.bars[i]||3)),bar=root.querySelector('[data-bar="'+b+'"]'),v=root.querySelector('[data-barval="'+b+'"]');if(bar)bar.style.width=width+'%';if(v)v.textContent=(r.barText&&r.barText[i])||Math.round(width)+'%'});
  if(note)note.textContent=r.note||'';
 }
 root.querySelectorAll('[data-in]').forEach(function(el){el.addEventListener('input',function(){vals[el.dataset.in]=+el.value;update();if(done)done()})});
 update();
}
S.kinetics=function(root,done){formulaLab(root,{intro:'প্রতিক্রিয়ার হার তাপমাত্রা ও ঘনত্বের সঙ্গে কীভাবে বদলাতে পারে, একটি গুণগত মডেলে দেখুন।',inputs:[{k:'temp',l:'Temperature',min:10,max:80,step:5,v:25,unit:' °C'},{k:'conc',l:'Relative concentration',min:1,max:10,step:1,v:5}],bars:['Temperature effect','Concentration effect'],labels:['Relative rate index','Rate interpretation'],calc:function(v){var t=Math.pow(2,(v.temp-25)/20),c=v.conc/5,rate=t*c;return{results:[rate.toFixed(2)+'×',rate>2?'দ্রুততর':rate<.7?'ধীরতর':'মাঝারি'],bars:[Math.min(100,t/Math.pow(2,2.75)*100),v.conc*10],barText:[t.toFixed(2)+'×',c.toFixed(1)+'×'],note:'তাপমাত্রা বাড়লে কার্যকর সংঘর্ষের অংশ সাধারণত বাড়ে; প্রকৃত হার নির্ভর করে activation energy ও reaction mechanism-এর ওপর।'}}} ,done)};
S.equilibrium=function(root,done){formulaLab(root,{intro:'A ⇌ B ধরনের একটি সরল মডেলে Q ও K তুলনা করে কোন দিকে পরিবর্তন হবে তা অনুধাবন করুন।',inputs:[{k:'a',l:'Reactant A amount',min:1,max:10,step:1,v:6},{k:'b',l:'Product B amount',min:1,max:10,step:1,v:4}],bars:['Reactant A','Product B'],labels:['Illustrative Q = B/A','Initial tendency'],calc:function(v){var q=v.b/v.a;return{results:[q.toFixed(2),q<1?'Products-এর দিকে':q>1?'Reactants-এর দিকে':'এই সরল মডেলে ভারসাম্য'],bars:[v.a*10,v.b*10],barText:[String(v.a),String(v.b)],note:'এটি ব্যাখ্যামূলক অনুপাত; বাস্তব equilibrium constant নির্ভর করে সুষম সমীকরণ, তাপমাত্রা ও সক্রিয়তার ওপর।'}}} ,done)};
S.ph=function(root,done){formulaLab(root,{intro:'pH স্কেলে এক ধাপ পরিবর্তন মানে হাইড্রোজেন আয়ন ঘনত্বে দশগুণ পরিবর্তন।',inputs:[{k:'ph',l:'pH value',min:0,max:14,step:1,v:7}],bars:['Acidity','Basicity'],labels:['[H⁺] (mol/L, ideal)','Solution type'],calc:function(v){var h=Math.pow(10,-v.ph);return{results:[h.toExponential(1),v.ph<7?'Acidic':v.ph>7?'Basic':'Neutral'],bars:[Math.max(2,(14-v.ph)/14*100),Math.max(2,v.ph/14*100)],barText:['pH '+v.ph,'pH '+v.ph],note:'সাধারণ জলীয় দ্রবণে ২৫°C-এ pH = −log₁₀[H⁺] ধরা হয়; বাস্তব দ্রবণে activity গুরুত্বপূর্ণ।'}}} ,done)};
S.titration=function(root,done){formulaLab(root,{intro:'শক্তিশালী অ্যাসিড–শক্তিশালী ক্ষারের একটি সরলীকৃত titration curve অন্বেষণ করুন।',inputs:[{k:'vol',l:'Titrant added',min:0,max:50,step:1,v:10,unit:' mL'},{k:'conc',l:'Titrant concentration',min:5,max:20,step:1,v:10,unit:' mmol/L'}],bars:['Acid remaining','Base added'],labels:['Illustrative pH','Titration stage'],calc:function(v){var eq=25*10/v.conc,delta=v.vol-eq,ph=7+7*Math.tanh(delta/3.2);return{results:[ph.toFixed(2),Math.abs(delta)<2?'Equivalence region':delta<0?'Before equivalence':'After equivalence'],bars:[Math.max(2,100-v.vol*2),Math.min(100,v.vol*2)],barText:[Math.max(0,50-v.vol)+' mL',''+v.vol+' mL'],note:'শিক্ষামূলক স্কেচ: প্রকৃত equivalence volume প্রাথমিক নমুনার পরিমাণ ও ঘনত্বের ওপর নির্ভর করে।'}}} ,done)};
S.electrochem=function(root,done){formulaLab(root,{intro:'ঘনত্বের অনুপাত cell potential-কে কীভাবে প্রভাবিত করে, Nernst সমীকরণের ধারণা দিয়ে দেখুন।',inputs:[{k:'ratio',l:'Ion concentration ratio',min:1,max:100,step:1,v:10},{k:'temp',l:'Temperature',min:10,max:60,step:5,v:25,unit:' °C'}],bars:['Concentration effect','Temperature factor'],labels:['Illustrative E (V)','Trend'],calc:function(v){var E=1.10-(0.0592*(v.temp+273.15)/298.15)*Math.log10(v.ratio);return{results:[E.toFixed(3)+' V',E<1.05?'Potential decreases':'Near standard potential'],bars:[Math.max(3,100-Math.log10(v.ratio)*20),v.temp/60*100],barText:[v.ratio+':1',v.temp+' °C'],note:'এটি একটি সরল concentration-cell approximation; বাস্তব কোষে half-cell reactions ও ion charges বসাতে হয়।'}}} ,done)};
S.optics=function(root,done){
 root.innerHTML='';var intro=document.createElement('p');intro.className='sim-intro';intro.textContent='উত্তল লেন্স: বস্তু দূরত্ব ও ফোকাল দৈর্ঘ্য বদলান। প্রধান অক্ষ বরাবর সমান্তরাল রশ্মি লেন্সের পরে ফোকাস দিয়ে যায়; কেন্দ্র দিয়ে যাওয়া রশ্মি প্রায় সোজা চলে।';root.appendChild(intro);
 var panel=document.createElement('div');panel.className='lens-sim';panel.innerHTML='<div class="lens-controls"><label>বস্তুর দূরত্ব (u)<output id="lens-u-out">40 cm</output><input id="lens-u" type="range" min="12" max="100" value="40"></label><label>ফোকাল দৈর্ঘ্য (f)<output id="lens-f-out">10 cm</output><input id="lens-f" type="range" min="8" max="30" value="10"></label></div><div class="lens-stage"><svg viewBox="0 0 900 390" role="img" aria-label="উত্তল লেন্সের রশ্মিচিত্র"><defs><marker id="lensArrow" markerWidth="7" markerHeight="7" refX="5" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="#fb7185"/></marker></defs><rect width="900" height="390" rx="14" fill="#fff"/><line x1="25" y1="195" x2="875" y2="195" stroke="#555" stroke-width="1.5"/><g id="lens-rays"></g><path d="M450 55 Q405 195 450 335 Q495 195 450 55Z" fill="#67e8f9" fill-opacity=".55" stroke="#06b6d4" stroke-width="2"/><g fill="#111" font-size="15"><text x="450" y="28" text-anchor="middle">উত্তল লেন্স</text><text id="lens-f1" y="220" text-anchor="middle">F</text><text id="lens-f2" y="220" text-anchor="middle">F</text><text id="lens-2f1" y="242" text-anchor="middle">2F</text><text id="lens-2f2" y="242" text-anchor="middle">2F</text></g></svg></div><div class="lens-results" aria-live="polite"><b id="lens-v">প্রতিবিম্বের দূরত্ব: —</b><span id="lens-type">প্রতিবিম্বের প্রকৃতি: —</span><span id="lens-mag">বিবর্ধন: —</span></div><p class="lens-note">সূত্র: 1/f = 1/v + 1/u (দূরত্বের মান ব্যবহার করা হয়েছে)। f &lt; u &lt; 2f হলে বাস্তব, উল্টো ও বিবর্ধিত প্রতিবিম্ব হয়; u = f হলে প্রতিবিম্ব অসীমে গঠিত হয়।</p>';
 root.appendChild(panel);var ui=panel.querySelector('#lens-u'),fi=panel.querySelector('#lens-f'),svg=panel.querySelector('#lens-rays');
 function draw(){var u=+ui.value,f=+fi.value;panel.querySelector('#lens-u-out').textContent=u+' cm';panel.querySelector('#lens-f-out').textContent=f+' cm';var v=u===f?Infinity:(f*u)/(u-f),mag=u===f?Infinity:v/u;var ox=Math.max(60,450-u*3.4),oy=125,fx=450-f*3.4,fx2=450+f*3.4,tw=450+2*f*3.4;function yy(x,y0,x1,y1,x2){return y0+(y1-y0)*(x2-x)/(x1-x)}var imx=450+(isFinite(v)?v*3.4:390),imy=195-(isFinite(mag)?Math.max(-125,Math.min(125,mag*70)):125);imx=Math.max(475,Math.min(850,imx));
 var real=isFinite(v)&&v>0&&u>f,virtual=!isFinite(v)||v<0;var endx=real?imx:850,endy=real?imy:(195+(isFinite(mag)?Math.max(-100,Math.min(100,Math.abs(mag)*70)):100));
 svg.innerHTML='<line x1="'+ox+'" y1="195" x2="'+ox+'" y2="'+oy+'" stroke="#0d9488" stroke-width="10" stroke-linecap="round"/><path d="M '+ox+' '+oy+' L 450 '+oy+' L '+endx+' '+(real?endy:oy)+'" fill="none" stroke="#c2414b" stroke-width="1.8"/><path d="M '+ox+' '+oy+' L 450 '+oy+' L '+endx+' '+endy+'" fill="none" stroke="#c2414b" stroke-width="1.8"/><path d="M '+ox+' '+oy+' L 450 195 L '+endx+' '+endy+'" fill="none" stroke="#c2414b" stroke-width="1.8"/><line x1="'+fx+'" y1="185" x2="'+fx+'" y2="205" stroke="#111" stroke-width="2"/><line x1="'+fx2+'" y1="185" x2="'+fx2+'" y2="205" stroke="#111" stroke-width="2"/><line x1="'+(450-2*f*3.4)+'" y1="185" x2="'+(450-2*f*3.4)+'" y2="205" stroke="#111" stroke-width="2"/><line x1="'+tw+'" y1="185" x2="'+tw+'" y2="205" stroke="#111" stroke-width="2"/><line x1="'+(real?imx:850)+'" y1="195" x2="'+(real?imx:850)+'" y2="'+(real?endy:endy)+'" stroke="#fb923c" stroke-width="8" stroke-linecap="round" opacity=".9"/>';
 panel.querySelector('#lens-f1').setAttribute('x',fx);panel.querySelector('#lens-f2').setAttribute('x',fx2);panel.querySelector('#lens-2f1').setAttribute('x',450-2*f*3.4);panel.querySelector('#lens-2f2').setAttribute('x',tw);
 panel.querySelector('#lens-v').textContent='প্রতিবিম্বের দূরত্ব: '+(isFinite(v)?Math.abs(v).toFixed(1)+' cm':'অসীমে');panel.querySelector('#lens-type').textContent='প্রকৃতি: '+(!isFinite(v)?'অসীমে, খুব দূরে':real?'বাস্তব ও উল্টো':'কাল্পনিক ও সোজা');panel.querySelector('#lens-mag').textContent='বিবর্ধন: '+(isFinite(mag)?Math.abs(mag).toFixed(2)+'×':'অসীম');if(done)done();}
 ui.addEventListener('input',draw);fi.addEventListener('input',draw);draw();
};
S.magnetic=function(root,done){formulaLab(root,{intro:'দীর্ঘ সোজা তারের কাছে চৌম্বক ক্ষেত্রের গুণগত সম্পর্ক B ∝ I/r পরীক্ষা করুন।',inputs:[{k:'i',l:'Current',min:1,max:10,step:1,v:4,unit:' A'},{k:'r',l:'Distance from wire',min:1,max:10,step:1,v:3,unit:' cm'}],bars:['Current','Distance'],labels:['Relative field strength','Trend'],calc:function(v){var b=v.i/v.r;return{results:[b.toFixed(2)+' (relative)',b>1.5?'Stronger field':b<.5?'Weaker field':'Moderate field'],bars:[v.i*10,v.r*10],barText:[v.i+' A',v.r+' cm'],note:'দীর্ঘ সোজা তারের ক্ষেত্রে B = μ₀I/(2πr); এখানে অনুপাত দেখানো হয়েছে, calibrated absolute field নয়।'}}} ,done)};
S.periodic=function(root,done){formulaLab(root,{intro:'পর্যায় সারণিতে পারমাণবিক ব্যাসার্ধ ও তড়িৎঋণাত্মকতার সাধারণ প্রবণতা তুলনা করুন।',inputs:[{k:'period',l:'Position across period',min:1,max:8,step:1,v:4},{k:'group',l:'Position down group',min:1,max:7,step:1,v:3}],bars:['Atomic radius trend','Electronegativity trend'],labels:['Relative atomic radius','Relative electronegativity'],calc:function(v){var r=(9-v.period)*v.group,e=v.period/(v.group+.5);return{results:[r.toFixed(1)+' (relative)',e.toFixed(2)+' (relative)'],bars:[r/56*100,e/5*100],barText:['relative','relative'],note:'এটি পর্যায়গত প্রবণতার ধারণামূলক মানচিত্র, নির্দিষ্ট মৌলের পরীক্ষামূলক ডেটা নয়।'}}} ,done)};
S.bond=function(root,done){formulaLab(root,{intro:'দুটি পরমাণুর electronegativity পার্থক্য বাড়লে বন্ধনের polarity কীভাবে বাড়তে পারে দেখুন।',inputs:[{k:'en1',l:'Atom A electronegativity',min:0,max:4,step:.1,v:2.1},{k:'en2',l:'Atom B electronegativity',min:0,max:4,step:.1,v:3.0}],bars:['Atom A pull','Atom B pull'],labels:['Δ electronegativity','Qualitative bond'],calc:function(v){var d=Math.abs(v.en1-v.en2);return{results:[d.toFixed(1),d<.4?'Mostly non-polar':d<1.7?'Polar covalent':'High ionic character'],bars:[v.en1/4*100,v.en2/4*100],barText:[v.en1.toFixed(1),v.en2.toFixed(1)],note:'সীমাগুলো আনুমানিক নির্দেশক; bond type ধারাবাহিক, এবং molecular context-ও গুরুত্বপূর্ণ।'}}} ,done)};
S.stoich=function(root,done){formulaLab(root,{intro:'A + B → Product-এর 1:1 মোল অনুপাতে কোন reactant আগে শেষ হবে তা দেখুন।',inputs:[{k:'a',l:'Reactant A amount',min:1,max:20,step:1,v:12,unit:' mol'},{k:'b',l:'Reactant B amount',min:1,max:20,step:1,v:8,unit:' mol'}],bars:['Reactant A','Reactant B'],labels:['Maximum product','Limiting reagent'],calc:function(v){return{results:[Math.min(v.a,v.b)+' mol',v.a<v.b?'A is limiting':v.b<v.a?'B is limiting':'Both exactly consumed'],bars:[v.a/20*100,v.b/20*100],barText:[v.a+' mol',v.b+' mol'],note:'এই উদাহরণে stoichiometric ratio 1:1 ধরা হয়েছে; অন্য সমীকরণে সহগ অনুযায়ী হিসাব করতে হবে।'}}} ,done)};


S.integration=function(root,done){formulaLab(root,{intro:'নির্দিষ্ট ব্যবধানে y = x²-এর নিচের ক্ষেত্রফলকে rectangle approximation দিয়ে বোঝুন।',inputs:[{k:'n',l:'Number of rectangles',min:2,max:40,step:2,v:10},{k:'b',l:'Upper limit b',min:1,max:5,step:.5,v:3}],bars:['Rectangle estimate','Exact area'],labels:['Approximate area','Exact ∫₀ᵇ x² dx'],calc:function(v){var dx=v.b/v.n,sum=0;for(var i=0;i<v.n;i++)sum+=Math.pow((i+.5)*dx,2)*dx;var exact=Math.pow(v.b,3)/3;return{results:[sum.toFixed(3),exact.toFixed(3)],bars:[Math.min(100,sum/exact*100),100],barText:[(sum/exact*100).toFixed(1)+'%','100%'],note:'Midpoint rectangles ব্যবহার করা হয়েছে; rectangle সংখ্যা বাড়ালে approximation সাধারণত exact area-এর কাছাকাছি যায়।'}}} ,done)};
S.probability=function(root,done){formulaLab(root,{intro:'স্বাধীন Bernoulli trial-এর একটি মডেলে success probability ও trial সংখ্যা বদলে সম্ভাবনা দেখুন।',inputs:[{k:'p',l:'Success probability',min:5,max:95,step:5,v:30,unit:'%'},{k:'n',l:'Number of trials',min:1,max:20,step:1,v:5}],bars:['One success chance','At least one success'],labels:['Expected successes','P(at least one success)'],calc:function(v){var p=v.p/100,none=Math.pow(1-p,v.n),at=1-none;return{results:[(v.n*p).toFixed(2),(at*100).toFixed(1)+'%'],bars:[v.p,at*100],barText:[v.p+'%',(at*100).toFixed(1)+'%'],note:'ধরা হয়েছে প্রতিটি trial স্বাধীন এবং প্রতিবার success probability একই থাকে।'}}} ,done)};

/* Rutherford alpha-scattering: animated trajectories with adjustable energy and nucleus charge. */
S.rutherford=function(root,done){
 var P=pal(),cv=mk(root,680,340),x=cv.x,shots=[],running=true,clock=0;
 var v=controls(root,[{k:'Z',l:'Nuclear charge (relative Z)',min:10,max:90,step:5,v:40},{k:'E',l:'Alpha energy',min:1,max:10,step:1,v:5},{k:'rate',l:'Animation speed',min:.5,max:2,step:.1,v:1}],function(){done&&done()});
 var ro=readouts(root,[['sent','Particles launched',''],['large','Large deflections',''],['back','Backscattered','']]);
 btns(root,[['▶ Start beam',function(){running=true;done&&done()},'pri'],['⏸ Pause',function(){running=false}],['↺ Reset',function(){shots=[];clock=0;done&&done()}],['Fire 12 alpha particles',function(){for(var i=0;i<12;i++)shots.push({y:65+i*18,x:55,t:0,vy:0,back:false,done:false,seed:i});done&&done()}]]);
 function launch(){shots.push({y:50+Math.random()*240,x:52,t:0,vy:0,back:false,done:false,seed:Math.random()});if(shots.length>70)shots.shift()}
 var spawn=0,large=0,back=0;
 loop(root,function(dt){if(running){clock+=dt*v.rate;spawn+=dt*v.rate;if(spawn>.28){spawn=0;launch()}}
  var W=cv.w,H=cv.h,nx=425,ny=H/2,rad=12+v.Z*.22;x.clearRect(0,0,W,H);
  // gold foil plane and atom nucleus
  x.fillStyle='rgba(251,191,36,.11)';x.fillRect(320,20,4,H-40);x.strokeStyle=P.a+'99';x.setLineDash([3,6]);x.beginPath();x.moveTo(322,20);x.lineTo(322,H-20);x.stroke();x.setLineDash([]);
  for(var j=0;j<5;j++){x.strokeStyle='rgba(125,190,230,.13)';x.beginPath();x.arc(nx,ny,rad+18+j*17,0,TAU);x.stroke()}
  dot(x,nx,ny,rad,'#fb7185',20);dot(x,nx,ny,rad*.45,'#fecdd3',5);x.fillStyle=P.tx;x.font='12px sans-serif';x.textAlign='center';x.fillText('ধনাত্মক নিউক্লিয়াস',nx,ny+rad+24);x.fillText('পাতলা সোনার পাত',322,16);
  shots.forEach(function(s){if(!s.done&&running){var dx=nx-s.x,dy=ny-s.y,dist=Math.sqrt(dx*dx+dy*dy);var force=(v.Z/(v.E*dist*dist+12))*1800;s.vy+=(ny-s.y)/(dist||1)*force*dt; s.x+=(s.back?-110:210)*dt*v.rate; s.y+=s.vy*dt*v.rate;if(s.x>nx+rad+12&& !s.back && Math.abs(s.y-ny)<rad*1.3){s.back=true;back++}if(s.x>W+20||s.y<0||s.y>H||s.x<0){s.done=true;if(Math.abs(s.y-s.y0)>35)large++}if(s.x>nx-70&&s.x<nx+rad+10&&Math.abs(s.y-ny)<rad+10){s.back=true;s.vy+=(s.y<ny?-1:1)*30;}}
   x.beginPath();x.moveTo(s.x-22,s.y);x.lineTo(s.x,s.y);x.strokeStyle='#fde68a';x.lineWidth=2;x.stroke();dot(x,s.x,s.y,4,'#fbbf24',8);
  });shots=shots.filter(function(s){return !s.done});ro('sent',String(Math.max(0,Math.floor(clock/.28))));ro('large',String(large));ro('back',String(back));
  x.fillStyle=P.tx;x.textAlign='left';x.font='12px sans-serif';x.fillText('α-কণা →',18,24);x.fillText('নিউক্লিয়াসের কাছে গেলে বিচ্যুতি বাড়ে',18,H-12);
 });};
/* Bohr shell model: choose element, select individual electrons, play/pause and inspect shells. */
S.bohr=function(root,done){
 var P=pal(),cv=mk(root,680,380),x=cv.x,phase=0,paused=false,selected=0;
 var atoms={H:{name:'Hydrogen',z:1,shell:[1]},He:{name:'Helium',z:2,shell:[2]},Li:{name:'Lithium',z:3,shell:[2,1]},C:{name:'Carbon',z:6,shell:[2,4]},O:{name:'Oxygen',z:8,shell:[2,6]},Na:{name:'Sodium',z:11,shell:[2,8,1]},Mg:{name:'Magnesium',z:12,shell:[2,8,2]},Cl:{name:'Chlorine',z:17,shell:[2,8,7]},Ar:{name:'Argon',z:18,shell:[2,8,8]}};
 var chosen='Na',els=[];var bar=document.createElement('div');bar.className='ctl';bar.innerHTML='<label class="control"><span>মৌল নির্বাচন</span><select id="bohrAtom" aria-label="মৌল নির্বাচন"><option value="H">H · Hydrogen</option><option value="He">He · Helium</option><option value="Li">Li · Lithium</option><option value="C">C · Carbon</option><option value="O">O · Oxygen</option><option value="Na" selected>Na · Sodium</option><option value="Mg">Mg · Magnesium</option><option value="Cl">Cl · Chlorine</option><option value="Ar">Ar · Argon</option></select></label><div class="control"><span>Animation</span><button type="button" class="btn pri" id="bohrPlay">⏸ Pause</button></div><div class="control"><span>নির্বাচিত ইলেকট্রন</span><strong id="bohrInfo">Electron 1</strong></div></div>';root.insertBefore(bar,cv.c);
 var note=document.createElement('p');note.className='mutt';note.textContent='ইলেকট্রনকে নির্বাচন করতে তার ওপর ট্যাপ/ক্লিক করুন। শেলগুলো ধারণাগত শক্তিস্তর; ইলেকট্রনের বাস্তব পথ নয়।';root.appendChild(note);
 function selectAtom(k){chosen=k;selected=0;var a=atoms[k];els=[];a.shell.forEach(function(n,si){for(var j=0;j<n;j++)els.push({shell:si+1,ang:TAU*j/n+si*.27,id:els.length+1})});var inf=root.querySelector('#bohrInfo');if(inf)inf.textContent='Electron 1 · shell '+els[0].shell;done&&done()}
 root.querySelector('#bohrAtom').addEventListener('change',function(e){selectAtom(e.target.value)});root.querySelector('#bohrPlay').addEventListener('click',function(e){paused=!paused;e.target.textContent=paused?'▶ Play':'⏸ Pause';done&&done()});selectAtom(chosen);
 cv.c.addEventListener('click',function(e){var p=cv.pt(e),cx=cv.w/2,cy=cv.h/2;var best=-1,bd=22;els.forEach(function(el,i){var r=el.shell*43,xx=cx+Math.cos(el.ang+phase)*r,yy=cy+Math.sin(el.ang+phase)*r,d=Math.hypot(xx-p.x,yy-p.y);if(d<bd){bd=d;best=i}});if(best>=0){selected=best;var inf=root.querySelector('#bohrInfo');if(inf)inf.textContent='Electron '+els[best].id+' · shell '+els[best].shell;done&&done()}});
 loop(root,function(dt){if(!paused)phase+=dt*.8;var W=cv.w,H=cv.h,cx=W/2,cy=H/2;x.clearRect(0,0,W,H);var a=atoms[chosen];for(var sh=1;sh<=a.shell.length;sh++){x.beginPath();x.arc(cx,cy,sh*43,0,TAU);x.strokeStyle=sh===els[selected]?.shell?'rgba(251,191,36,.8)':'rgba(125,190,230,.35)';x.lineWidth=sh===els[selected]?.shell?2.5:1.4;x.stroke();x.fillStyle=P.tx;x.font='11px sans-serif';x.textAlign='left';x.fillText('n='+sh,cx+sh*43+4,cy-4)}
  dot(x,cx,cy,Math.max(13,Math.min(25,a.z*1.1)),'#fb7185',18);x.fillStyle='#fff';x.font='bold 12px sans-serif';x.textAlign='center';x.fillText(a.z+'p⁺',cx,cy+4);
  els.forEach(function(el,i){var r=el.shell*43,ang=el.ang+phase*(1/(el.shell*.65));var xx=cx+Math.cos(ang)*r,yy=cy+Math.sin(ang)*r;dot(x,xx,yy,i===selected?7:5,i===selected?'#fbbf24':'#67e8f9',i===selected?18:10);if(i===selected){x.strokeStyle='#fbbf24';x.lineWidth=1.5;x.beginPath();x.arc(xx,yy,12,0,TAU);x.stroke()}});
  x.fillStyle=P.tx;x.textAlign='left';x.font='12px sans-serif';x.fillText(a.name+' · Z = '+a.z+' · electrons = '+els.length,18,22);x.fillText('Shell occupancy: '+a.shell.join(' · '),18,H-14);
 });};


/* Dedicated Qualitative Chemistry concept simulations: each topic has its own interaction. */
S.dalton=function(root,done){var cv=mk(root,680,280),x=cv.x,mode=0;var bs=btns(root,[['Add atoms',function(){mode=Math.min(12,mode+1);done&&done()}],['Reset',function(){mode=0;done&&done()}]]);loop(root,function(dt,t){x.clearRect(0,0,cv.w,cv.h);x.fillStyle='#071421';x.fillRect(0,0,cv.w,cv.h);x.fillStyle='#9fb6cb';x.font='14px sans-serif';x.fillText('Dalton model · neutral solid spheres',18,24);for(var i=0;i<Math.max(4,mode+4);i++){var px=70+(i%6)*105,py=75+Math.floor(i/6)*100;x.beginPath();x.arc(px,py,25,0,TAU);x.fillStyle=['#38bdf8','#fbbf24','#34d399'][i%3];x.fill();x.fillStyle='#071421';x.font='12px sans-serif';x.fillText(['A','B','A'][i%3],px-4,py+4)}x.fillStyle='#e2e8f0';x.fillText('Different elements are represented by different atom types.',18,260)})};
S.thomson=function(root,done){var cv=mk(root,680,300),x=cv.x,neg=5;var c=controls(root,[{k:'e',l:'ইলেকট্রন সংখ্যা',min:1,max:12,v:5}],function(k,v){neg=v;done&&done()});loop(root,function(dt,t){x.clearRect(0,0,cv.w,cv.h);x.fillStyle='#071421';x.fillRect(0,0,cv.w,cv.h);x.beginPath();x.ellipse(340,150,210,105,0,0,TAU);x.fillStyle='rgba(248,113,113,.22)';x.fill();x.strokeStyle='#f87171';x.lineWidth=2;x.stroke();x.fillStyle='#fecaca';x.font='15px sans-serif';x.fillText('Diffuse positive charge',270,150);for(var i=0;i<neg;i++){var a=i/neg*TAU+t*.25,px=340+Math.cos(a)*155,py=150+Math.sin(a)*65;x.beginPath();x.arc(px,py,9,0,TAU);x.fillStyle='#38bdf8';x.fill();x.fillStyle='#06111d';x.font='12px sans-serif';x.fillText('−',px-3,py+4)}x.fillStyle='#cbd5e1';x.fillText('Tap the slider: electrons sit within the positive sphere.',18,280)})};
S.cathode=function(root,done){var cv=mk(root,680,260),x=cv.x;var v=controls(root,[{k:'v',l:'Accelerating voltage',min:1,max:10,v:5}],function(){done&&done()});loop(root,function(dt,t){x.clearRect(0,0,cv.w,cv.h);x.fillStyle='#071421';x.fillRect(0,0,cv.w,cv.h);x.fillStyle='#334155';x.fillRect(35,75,65,110);x.fillRect(580,75,65,110);x.fillStyle='#fbbf24';x.fillText('Cathode (−)',28,60);x.fillStyle='#34d399';x.fillText('Anode (+)',580,60);x.strokeStyle='#38bdf8';x.lineWidth=3;x.beginPath();x.moveTo(100,130);x.lineTo(580,130);x.stroke();for(var i=0;i<10;i++){var px=110+((t*70+i*45)%455);x.beginPath();x.arc(px,130+Math.sin(t*4+i)*9,4,0,TAU);x.fillStyle='#7dd3fc';x.fill()}x.fillStyle='#e2e8f0';x.fillText('Electron beam travels from cathode toward anode',180,220)})};
S.spectrum=function(root,done){var cv=mk(root,680,260),x=cv.x,level=4;var v=controls(root,[{k:'n',l:'উচ্চ শক্তিস্তর n',min:2,max:6,v:4}],function(k,n){level=n;done&&done()});loop(root,function(dt,t){x.clearRect(0,0,cv.w,cv.h);x.fillStyle='#071421';x.fillRect(0,0,cv.w,cv.h);for(var i=1;i<=6;i++){var y=220-i*28;x.strokeStyle=i===level?'#fbbf24':'#426078';x.lineWidth=i===level?3:1;x.beginPath();x.moveTo(35,y);x.lineTo(390,y);x.stroke();x.fillStyle='#cbd5e1';x.fillText('n='+i,8,y+4)}var y1=220-level*28,y2=220-1*28;x.strokeStyle='#fb7185';x.lineWidth=2;x.beginPath();x.moveTo(280,y1);x.lineTo(280,y2);x.stroke();x.fillStyle='#fb7185';x.fillText('Photon emitted',410,90);var colors=['#7c3aed','#3b82f6','#22c55e','#facc15','#f97316','#ef4444'];for(var j=0;j<level-1;j++){x.fillStyle=colors[j%colors.length];x.fillRect(420+j*30,130,20,45)}x.fillStyle='#cbd5e1';x.fillText('Larger energy drop → higher-energy photon',390,205)})};
S.quantum=function(root,done){var cv=mk(root,680,280),x=cv.x;var v=controls(root,[{k:'n',l:'n (principal)',min:1,max:5,v:3},{k:'l',l:'l (angular)',min:0,max:4,v:1}],function(){done&&done()});loop(root,function(){var n=+root.querySelectorAll('.ctl input')[0].value,l=+root.querySelectorAll('.ctl input')[1].value;x.clearRect(0,0,cv.w,cv.h);x.fillStyle='#071421';x.fillRect(0,0,cv.w,cv.h);var valid=l<n; x.fillStyle=valid?'#34d399':'#f87171';x.font='bold 22px sans-serif';x.fillText(valid?'Allowed combination':'Not allowed: l must be < n',25,45);x.fillStyle='#cbd5e1';x.font='16px sans-serif';x.fillText('For n = '+n+', valid l values: 0 to '+(n-1),25,90);x.fillText('mₗ ranges from −l to +l; mₛ = ±½',25,125);for(var i=0;i<n;i++){x.beginPath();x.arc(80+i*65,200,22,0,TAU);x.fillStyle=i<=l?'#38bdf8':'#24394b';x.fill();x.fillStyle='#071421';x.fillText(''+i,76+i*65,205)}})};
S.orbitals=function(root,done){var cv=mk(root,680,280),x=cv.x,shape='p';var b=btns(root,[['s orbital',function(){shape='s';done&&done()}],['p orbital',function(){shape='p';done&&done()}],['d orbital',function(){shape='d';done&&done()}]]);loop(root,function(dt,t){x.clearRect(0,0,cv.w,cv.h);x.fillStyle='#071421';x.fillRect(0,0,cv.w,cv.h);x.strokeStyle='#526a80';x.beginPath();x.moveTo(340,35);x.lineTo(340,245);x.moveTo(230,140);x.lineTo(450,140);x.stroke();x.fillStyle='rgba(56,189,248,.3)';x.strokeStyle='#38bdf8';if(shape==='s'){x.beginPath();x.arc(340,140,70,0,TAU);x.fill();x.stroke()}else if(shape==='p'){x.beginPath();x.ellipse(310,140,28,68,0,0,TAU);x.ellipse(370,140,28,68,0,0,TAU);x.fill();x.stroke()}else{for(var a=0;a<4;a++){var an=a*Math.PI/2+.3;x.beginPath();x.ellipse(340+Math.cos(an)*42,140+Math.sin(an)*42,48,23,an,0,TAU);x.fill();x.stroke()}}x.fillStyle='#e2e8f0';x.fillText(shape+' orbital shape (schematic)',20,25)})};
S.aufbau=function(root,done){var cv=mk(root,680,270),x=cv.x,e=6;var v=controls(root,[{k:'e',l:'ইলেকট্রন সংখ্যা',min:1,max:20,v:6}],function(k,n){e=n;done&&done()});var levels=['1s','2s','2p','3s','3p','4s','3d'];loop(root,function(){e=+root.querySelector('.ctl input').value;x.clearRect(0,0,cv.w,cv.h);x.fillStyle='#071421';x.fillRect(0,0,cv.w,cv.h);var rem=e;levels.forEach(function(l,i){var cap=l.endsWith('p')?6:l.endsWith('d')?10:2,filled=Math.min(cap,rem);rem-=filled;var y=42+i*31;x.fillStyle='#cbd5e1';x.fillText(l,20,y+15);for(var j=0;j<cap/2;j++){var px=95+j*46;x.strokeStyle='#547087';x.strokeRect(px,y,38,22);if(filled>j*2){x.fillStyle='#38bdf8';x.fillText('↑',px+8,y+16)}if(filled>j*2+1){x.fillStyle='#fbbf24';x.fillText('↓',px+23,y+16)}}});x.fillStyle='#e2e8f0';x.fillText('Electrons fill lower-energy orbitals first (schematic)',360,25)})};
S.pauli=function(root,done){var cv=mk(root,680,250),x=cv.x,count=1;var v=controls(root,[{k:'n',l:'এই অরবিটালে ইলেকট্রন',min:0,max:3,v:2}],function(){done&&done()});loop(root,function(){count=+root.querySelector('.ctl input').value;x.clearRect(0,0,cv.w,cv.h);x.fillStyle='#071421';x.fillRect(0,0,cv.w,cv.h);x.strokeStyle='#38bdf8';x.lineWidth=2;x.strokeRect(260,70,160,100);if(count>=1){x.fillStyle='#38bdf8';x.font='40px sans-serif';x.fillText('↑',295,130)}if(count>=2){x.fillStyle='#fbbf24';x.fillText('↓',350,130)}x.fillStyle=count>2?'#f87171':'#34d399';x.font='bold 18px sans-serif';x.fillText(count>2?'Invalid: max 2 electrons':'Allowed occupancy',230,205);x.fillStyle='#cbd5e1';x.font='14px sans-serif';x.fillText('Pauli exclusion: same orbital → opposite spins',190,235)})};
S.isotope=function(root,done){var cv=mk(root,680,270),x,z=6,n=6;var v=controls(root,[{k:'z',l:'প্রোটন',min:1,max:20,v:6},{k:'n',l:'নিউট্রন',min:0,max:24,v:6}],function(){done&&done()});loop(root,function(){var a=root.querySelectorAll('.ctl input');z=+a[0].value;n=+a[1].value;x.clearRect(0,0,cv.w,cv.h);x.fillStyle='#071421';x.fillRect(0,0,cv.w,cv.h);x.fillStyle='#cbd5e1';x.font='17px sans-serif';x.fillText('Atomic number Z = '+z,25,35);x.fillText('Mass number A = '+(z+n),25,65);x.fillText('Neutrons N = A − Z = '+n,25,95);for(var i=0;i<z+n;i++){var px=350+(i%9)*22,py=75+Math.floor(i/9)*22;x.beginPath();x.arc(px,py,8,0,TAU);x.fillStyle=i<z?'#fb7185':'#38bdf8';x.fill()}x.fillStyle='#fb7185';x.fillText('● proton',350,235);x.fillStyle='#38bdf8';x.fillText('● neutron',450,235)})};
S.shellCapacity=function(root,done){var cv=mk(root,680,270),x,n=3;var v=controls(root,[{k:'n',l:'প্রধান শক্তিস্তর n',min:1,max:7,v:3}],function(){done&&done()});loop(root,function(t,tm){n=+root.querySelector('.ctl input').value;x.clearRect(0,0,cv.w,cv.h);x.fillStyle='#071421';x.fillRect(0,0,cv.w,cv.h);for(var i=1;i<=n;i++){x.beginPath();x.arc(250,135,i*25,0,TAU);x.strokeStyle=i===n?'#fbbf24':'#38bdf8';x.lineWidth=i===n?3:1;x.stroke()}x.fillStyle='#e2e8f0';x.font='18px sans-serif';x.fillText('Shell n = '+n,440,100);x.fillText('Maximum capacity = 2n² = '+(2*n*n),440,135);x.fillText('Capacity is a limit, not fill order.',440,175)})};
S.hund=function(root,done){var cv=mk(root,680,250),x,e=4;var v=controls(root,[{k:'e',l:'p উপস্তরের ইলেকট্রন',min:0,max:6,v:4}],function(){done&&done()});loop(root,function(){e=+root.querySelector('.ctl input').value;x.clearRect(0,0,cv.w,cv.h);x.fillStyle='#071421';x.fillRect(0,0,cv.w,cv.h);var rem=e;for(var i=0;i<3;i++){var px=190+i*100;x.strokeStyle='#38bdf8';x.strokeRect(px,75,70,80);if(rem>0){x.fillStyle='#38bdf8';x.font='34px sans-serif';x.fillText('↑',px+16,125);rem--}if(e>3&&rem>0){x.fillStyle='#fbbf24';x.fillText('↓',px+42,125);rem--}}x.fillStyle='#cbd5e1';x.font='16px sans-serif';x.fillText('Three p orbitals fill singly before pairing',175,205)})};
S.electronConfig=function(root,done){var cv=mk(root,680,250),x,z=17;var v=controls(root,[{k:'z',l:'পারমাণবিক সংখ্যা (নিরপেক্ষ পরমাণু)',min:1,max:30,v:17}],function(){done&&done()});loop(root,function(){z=+root.querySelector('.ctl input').value;x.clearRect(0,0,cv.w,cv.h);x.fillStyle='#071421';x.fillRect(0,0,cv.w,cv.h);var order=[['1s',2],['2s',2],['2p',6],['3s',2],['3p',6],['4s',2],['3d',10]],rem=z,txt=[];order.forEach(function(it){var n=Math.min(rem,it[1]);if(n>0)txt.push(it[0]+(n===1?'¹':n===2?'²':n===3?'³':n===4?'⁴':n===5?'⁵':n===6?'⁶':n===7?'⁷':n===8?'⁸':n===9?'⁹':'¹⁰'));rem-=n});x.fillStyle='#38bdf8';x.font='bold 24px sans-serif';x.fillText('Z = '+z,25,50);x.fillStyle='#e2e8f0';x.font='20px sans-serif';var lines=[];for(var i=0;i<txt.length;i+=4)lines.push(txt.slice(i,i+4).join(' '));lines.forEach(function(l,i){x.fillText(l,25,105+i*35)});x.fillStyle='#94a3b8';x.font='14px sans-serif';x.fillText('Educational Aufbau sequence; exceptions exist for some elements.',25,220)})};
S.valence=function(root,done){var cv=mk(root,680,260),x,n=1;var v=controls(root,[{k:'n',l:'বহিঃস্ত ইলেকট্রন',min:1,max:8,v:1}],function(){done&&done()});loop(root,function(){n=+root.querySelector('.ctl input').value;x.clearRect(0,0,cv.w,cv.h);x.fillStyle='#071421';x.fillRect(0,0,cv.w,cv.h);x.beginPath();x.arc(230,130,35,0,TAU);x.fillStyle='#fb7185';x.fill();for(var i=0;i<n;i++){var a=i/n*TAU;x.beginPath();x.arc(230+Math.cos(a)*90,130+Math.sin(a)*90,7,0,TAU);x.fillStyle='#38bdf8';x.fill()}x.fillStyle='#e2e8f0';x.font='18px sans-serif';x.fillText('Valence electrons: '+n,390,100);x.fillText(n<=4?'Model: electron loss may be favourable':'Model: electron gain may be favourable',390,140);x.fillStyle='#94a3b8';x.font='13px sans-serif';x.fillText('Qualitative guide; actual chemistry varies by element.',390,175)})};
