S.electroncloud=function(root,done){var cv=mk(root,680,280),x,density=55;var v=controls(root,[{k:'d',l:'Probability cloud density',min:10,max:100,v:55}],function(){done&&done()});loop(root,function(dt,t){density=+root.querySelector('.ctl input').value;x.clearRect(0,0,cv.w,cv.h);x.fillStyle='#071421';x.fillRect(0,0,cv.w,cv.h);x.beginPath();x.arc(300,140,18,0,TAU);x.fillStyle='#fb7185';x.fill();for(var i=0;i<density*2;i++){var a=i*2.39996,r=20+Math.sqrt((i%density)/density)*110,px=300+Math.cos(a+t*.03)*r,py=140+Math.sin(a+t*.03)*r*.78;x.fillStyle='rgba(56,189,248,'+(0.12+0.3*(1-r/150))+')';x.beginPath();x.arc(px,py,1.5+(density/100),0,TAU);x.fill()}x.fillStyle='#e2e8f0';x.font='17px sans-serif';x.fillText('Electron probability cloud (schematic)',20,25);x.fillText('Denser regions represent greater probability.',360,235)})};
