S.isotopeCompare=function(root,done){var cv=mk(root,680,260),x;var v=controls(root,[{k:'a',l:'Isotope A mass number',min:1,max:40,v:12},{k:'b',l:'Isotope B mass number',min:1,max:40,v:14},{k:'z',l:'Shared atomic number Z',min:1,max:20,v:6}],function(){done&&done()});loop(root,function(){var a=root.querySelectorAll('.ctl input'),A=+a[0].value,B=+a[1].value,z=+a[2].value;x.clearRect(0,0,cv.w,cv.h);x.fillStyle='#071421';x.fillRect(0,0,cv.w,cv.h);x.fillStyle='#e2e8f0';x.font='18px sans-serif';x.fillText('Same Z = '+z+' → same element',25,35);x.fillText('A: N = '+(A-z)+'    B: N = '+(B-z),25,70);for(var j=0;j<2;j++){var N=(j?B:A)-z,px=190+j*220;x.beginPath();x.arc(px,150,Math.min(55,22+N),0,TAU);x.fillStyle=j?'#fbbf24':'#38bdf8';x.fill();x.fillStyle='#071421';x.fillText('Z='+z,px-17,145);x.fillText('N='+N,px-17,165)}x.fillStyle='#cbd5e1';x.fillText('Isotopes: same proton count, different neutron count.',150,240)})};
S.orbitalCount=function(root,done){var cv=mk(root,680,250),x;var v=controls(root,[{k:'l',l:'Azimuthal quantum number l',min:0,max:3,v:2}],function(){done&&done()});loop(root,function(){var l=+root.querySelector('.ctl input').value,count=2*l+1,names=['s','p','d','f'];x.clearRect(0,0,cv.w,cv.h);x.fillStyle='#071421';x.fillRect(0,0,cv.w,cv.h);x.fillStyle='#e2e8f0';x.font='20px sans-serif';x.fillText(names[l]+' has '+count+' orbital(s)',25,35);for(var i=0;i<count;i++){var px=35+(i%7)*88,py=85+Math.floor(i/7)*75;x.beginPath();x.ellipse(px+25,py+20,22,15,i*.2,0,TAU);x.fillStyle='rgba(56,189,248,.45)';x.fill();x.strokeStyle='#38bdf8';x.stroke()}x.fillStyle='#fbbf24';x.fillText('Total orbitals = 2l + 1 = '+count,25,225)})};
S.aufbauOrder=function(root,done){var cv=mk(root,680,250),x;var v=controls(root,[{k:'e',l:'ইলেকট্রন সংখ্যা',min:1,max:18,v:10}],function(){done&&done()});loop(root,function(){var e=+root.querySelector('.ctl input').value,seq=[['1s',2],['2s',2],['2p',6],['3s',2],['3p',6]],rem=e;x.clearRect(0,0,cv.w,cv.h);x.fillStyle='#071421';x.fillRect(0,0,cv.w,cv.h);seq.forEach(function(it,i){var n=Math.min(rem,it[1]);rem-=n;var y=38+i*40;x.fillStyle='#cbd5e1';x.fillText(it[0],25,y+17);x.fillStyle='#38bdf8';x.fillRect(90,y,Math.max(0,n/it[1])*450,22);x.strokeStyle='#567087';x.strokeRect(90,y,450,22);x.fillStyle='#e2e8f0';x.fillText(n+'/'+it[1],555,y+17)});x.fillStyle='#cbd5e1';x.fillText('Lower-energy subshells fill first.',25,245)})};
S.hundRule=function(root,done){var cv=mk(root,680,250),x;var v=controls(root,[{k:'e',l:'d উপস্তরের ইলেকট্রন',min:0,max:10,v:5}],function(){done&&done()});loop(root,function(){var e=+root.querySelector('.ctl input').value,rem=e;x.clearRect(0,0,cv.w,cv.h);x.fillStyle='#071421';x.fillRect(0,0,cv.w,cv.h);for(var i=0;i<5;i++){var px=80+i*105;x.strokeStyle='#38bdf8';x.strokeRect(px,70,60,70);if(rem>0){x.fillStyle='#38bdf8';x.font='30px sans-serif';x.fillText('↑',px+12,115);rem--}if(e>5&&rem>0){x.fillStyle='#fbbf24';x.fillText('↓',px+32,115);rem--}}x.fillStyle='#e2e8f0';x.font='16px sans-serif';x.fillText('Five d orbitals are singly occupied before pairing.',110,200)})};
S.valenceShell=function(root,done){var cv=mk(root,680,250),x;var v=controls(root,[{k:'e',l:'Valence electrons',min:1,max:8,v:7}],function(){done&&done()});loop(root,function(){var e=+root.querySelector('.ctl input').value;x.clearRect(0,0,cv.w,cv.h);x.fillStyle='#071421';x.fillRect(0,0,cv.w,cv.h);x.beginPath();x.arc(220,130,35,0,TAU);x.fillStyle='#fb7185';x.fill();x.strokeStyle='#38bdf8';x.beginPath();x.arc(220,130,90,0,TAU);x.stroke();for(var i=0;i<e;i++){var a=i/8*TAU-Math.PI/2;x.beginPath();x.arc(220+Math.cos(a)*90,130+Math.sin(a)*90,7,0,TAU);x.fillStyle='#fbbf24';x.fill()}x.fillStyle='#e2e8f0';x.font='18px sans-serif';x.fillText(e+' valence electron(s)',370,100);x.fillText(e>=5?'May gain/share electrons':'May lose/share electrons',370,140);x.fillStyle='#94a3b8';x.font='13px sans-serif';x.fillText('Qualitative guide only.',370,175)})};

